SourceCode.Declaration:
/// <summary>
/// A module switched off on Mobile module switches: Module is the HSMobileOpsModule element name (the app's WarehouseWorkflow), Message what the worker is told.
/// </summary>
[DataContractAttribute]
class HSMobileOpsModuleSwitchRow
{
    str        module;
    str        message;
}

Method.Source:
[DataMemberAttribute('Module')]
public str parmModule(str _value = module)
{
    module = _value;
    return module;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}
